export interface PasskeyCredentials {
  /**
   * Authenticator attestation GUID identifying the device type
   */
  aaguid: string | null;
  /**
   * Signature counter for replay attack prevention
   */
  counter: Generated<Int8>;
  created_at: Generated<Timestamp>;
  /**
   * Whether the credential is backed up (cloud-synced passkeys)
   */
  credential_backed_up: Generated<boolean | null>;
  /**
   * single_device, or multi_device for cloud-synced passkeys
   */
  credential_device_type: string | null;
  /**
   * Base64URL-encoded credential ID from WebAuthn registration
   */
  credential_id: string;
  /**
   * User-provided name for the passkey (e.g. "My phone", "Work laptop")
   */
  device_name: string | null;
  /**
   * Whether the passkey can sign in without an email (a discoverable credential): the browser's credProps rk at registration, else true (registration requires one); true once it has signed in without one; null when unknown (registered before it was recorded)
   */
  discoverable: boolean | null;
  id: Generated<number>;
  last_used_at: Timestamp | null;
  /**
   * Base64URL-encoded COSE public key
   */
  public_key: string;
  /**
   * Supported authenticator transports (usb, nfc, ble, internal, hybrid)
   */
  transports: string[] | null;
  updated_at: Generated<Timestamp | null>;
  /**
   * WebAuthn user handle (base64url) the passkey answers with: its account's (users.webauthn_user_id) for a passkey registered under it; for an older passkey, the one it returned at its first sign-in after that, null until then
   */
  user_handle: string | null;
  user_id: number;
  uuid: Generated<string>;
}

