export interface Sessions {
  /**
   * Which budget (tenant) this session is currently acting in; source of the per-request tenant GUC in a later phase.
   */
  active_tenant_id: number | null;
  /**
   * The user's password_changed_at when the session was created. A session older than the latest password change is invalid.
   */
  created_after_password_change_at: Timestamp | null;
  created_at: Generated<Timestamp>;
  device_info: Json | null;
  /**
   * Idle expiry. Requests slide it forward, up to the absolute lifetime counted from original_created_at.
   */
  expires_at: Timestamp;
  id: Generated<number>;
  ip_address: string | null;
  is_revoked: Generated<boolean>;
  /**
   * Last time the session was used for an authenticated request (written at most once per throttle interval).
   */
  last_activity_at: Generated<Timestamp | null>;
  /**
   * Last time the session token was rotated; decides when the next rotation is due.
   */
  last_rotated_at: Generated<Timestamp | null>;
  /**
   * When the user signed in. Rotation copies it to the new session, so the absolute session lifetime counts from here.
   */
  original_created_at: Generated<Timestamp>;
  /**
   * When the user last proved their password or passkey in this session (signing in counts). Minting tokens and enrolling passkeys need it to be recent.
   */
  reauthenticated_at: Timestamp | null;
  /**
   * Why the session was revoked, e.g. logout, logout_all, rotated, password_changed, admin_revoked, replaced_by_login.
   */
  revocation_reason: string | null;
  revoked_at: Timestamp | null;
  /**
   * The session this one replaced, when it was created by rotation.
   */
  rotated_from_session_id: number | null;
  /**
   * SHA-256 hash of the session token. The token itself is never stored.
   */
  session_token_hash: string;
  user_agent: string | null;
  user_id: number;
  uuid: Generated<string>;
}

